sources.evidence.nano:
module Evidence {
  record Source { origin: string verified: bool }
  record Evidence { count: int score: float source: Source }
  pure fn local(count: int): Evidence {
    Evidence(count: count, score: 1.0, source: Source(origin: "local", verified: true))
  }
}

sources.quality.nano:
import Evidence
module Quality {
  pure fn trusted(e: Evidence): bool { e.source.verified and e.count >= 2 }
}

sources.budget.nano:
import Evidence
module Budget {
  pure fn affordable(e: Evidence, tokens: int): bool { e.score >= 0.5 and tokens >= 100 }
}

sources.agent.nano:
import Evidence
import Quality
import Budget
strategy EvidenceGate {
  input evidence: Evidence
  input model_tokens: int
  every 1m {
    if trusted(evidence) and affordable(evidence, model_tokens) { execute() }
    else { pause() }
  }
}

sources.inline.nano:
import Evidence
strategy EvidenceGate {
  input evidence: Evidence
  input model_tokens: int
  every 1m {
    if (evidence.source.verified and evidence.count >= 2) and (evidence.score >= 0.5 and model_tokens >= 100) { execute() }
    else { pause() }
  }
}
